import java.util.*;class Solution{public String fractionToDecimal(int n,int d){if(n==0)return"0";long a=n,b=d;StringBuilder r=new StringBuilder();if((a<0)^(b<0))r.append('-');a=Math.abs(a);b=Math.abs(b);r.append(a/b);long rem=a%b;if(rem==0)return r.toString();r.append('.');Map<Long,Integer>m=new HashMap<>();while(rem!=0){if(m.containsKey(rem)){r.insert(m.get(rem),"(");r.append(')');break;}m.put(rem,r.length());rem*=10;r.append(rem/b);rem%=b;}return r.toString();}}
